from typing import List

from asr_service.backends.transcribe import Transcribe
from asr_service.backends.transcribe_options import BaseOptions
from asr_service.model.model_spec import ModelSpec
from shared.helper import deep_merge


class PresetPipeline:

    def __init__(self, name: str, options: List[BaseOptions]):
        self.name = name
        self.options = options

        pipe_types = []
        for option in self.options:
            pipe_type = BaseOptions.resolve_class_by_options_type(type(option))
            pipe_types.append(pipe_type)

        # self.optionsType = optionsType
        self.bases = tuple(t for t in pipe_types if t)
        self.Backend = type("Backend", self.bases, {})

    def get_class(self):
        return self.Backend

    def override_options(self, options: List[BaseOptions]):
        self.options = deep_merge(self.options, options, list_key=('base', 'process_type'))

    def supported_models(self) -> List[ModelSpec]:
        return self.instantiate(self.name).supported_models()

    def instantiate(self, name: str) -> Transcribe:
        return self.Backend(name, self.options)

    def to_json(self):
        return {
            "name": self.name,
            "mixins": [cls.__name__ for cls in self.bases],
            # "options_type": self.optionsType.__name__ if self.optionsType else None,
            # "options_schema": self.optionsType.model_json_schema() if self.optionsType else None,
        }
